architecture.h4_f:
msg = CBOR{v:1, text, reply_to, sent_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, text, reply_to?, thread_id?, mentions?, sent_at}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad=hex(room_id))
חוט = CBOR{
  v: 1,
  טקסט צופן: hex(ct), // אורך משתנה
  nonce: hex(12 B),
  sender_pseudo: hex(16 B),
  נשלח_ב: unix_ms
}

cryptoWire.h5_f:
חיצוני = CBOR{
  מקור_צומת: hex32,
  target_user: int64,
  inner_ciphertext: bytes,
  inner_nonce: בתים,
  נשלח_ב: unix_ms
}
sig = Ed25519-Sign(source_priv, outer)
POST /federation/deliver { envelope: outer, sig: hex64 }

auth.h1_f:
POST /api/authentication/register
  { username, password, x25519_public_key, display_name, phone?, email?, avatar_emoji }

תגובה 201 נוצרה:
  { access_token, refresh_token, user_id, username, ... }

auth.h3_f:
מטען access_token:
  { sub: user_id, jti: device_id, typ: "access", exp: now + 15min }
מטען refresh_token:
  { sub: user_id, jti: device_id, typ: "refresh", exp: now + 30d }

HS256 חתום עם סוד ה-64 בתים של הצומת מ-.env

auth.h4_f:
register_begin(): challenge = rand(32)
                    options = { rp.id, user.id, pubKeyCredParams, challenge }
                    אפשרויות החזרה

register_finish(אישור):
  אמת אישור מול TPM / שורש מובלעת מאובטח CA
  store { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR מטען = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  ← מכשיר חדש נרשם; JWTs חזרו.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
ciphertext = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

מסגרת מאוורר: { סוג:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {filename, size, chunk_size_hint}
            ← {upload_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
לסיים POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL על לא גמור: 24 שעות

presence.h1_f:
לקוח: בהקשה ראשונה → שלח {סוג:"t", state:"start"}
         אין יותר שליחה למשך 3 שניות אלא אם כן המצב משתנה
         10 שניות לאחר הקשה אחרונה ← שלח {סוג:"t", state:"stop"}
מקלט: עצירה אוטומטית 10 שניות לאחר ה"התחלה" האחרונה אם לא הגיעה "עצירה".

presence.h2_f:
POST /api/rooms/{id}/read { last_read_message_id }

if user.hides_receipts:
   לא להתמיד; לא לשדר
   אל תגיש למשתמש זה קבלות של אחרים
אחר:
   UPSERT אישורי קריאה VALUES (מזהה חדר, מזהה_משתמש, מזהה_הודעה, NOW())
   שידור {type:"r", room, user, message_id}

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS שידור {type:"c", kind:"invite", call_id}
WS שידור {type:"c", kind:"offer", sdp}
WS שידור {type:"c", kind:"answer", sdp}
WS שידור {type:"c", kind:"candidate",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
מעטפה = {
  מקור_צומת: hex32,
  target_user: int64,
  inner_ciphertext: bytes,
  inner_nonce : בתים,
  נשלח_בכתובת: unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(envelope))
POST /federation/deliver { envelope, sig }

gossip.h3_f:
מודעה = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(מודעה))
מטען רכילות: [..., {ad, sig}, ...]

מקלט: אמת את סיג מול ad.pubkey → חנות אם בסדר
נוסף: PoW של 2^18 אפסים מובילים ב-{pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template עם {
  אקראי = אקראי שלנו,
  server_name = שם המארח שלנו (או עטוף ב-ECH),
  session_id = מזהה הפגישה שלנו,
}
JA4 = t13d_xxxx_xxxx_xxxx (תואם את Chrome יציב הנוכחי)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {name: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: domain(t) = base32( SHA256(seed ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
אנדרואיד FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
אינטרנט SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
tool = sign_tool
input = עץ מקור, keys/release.key
מניפסט = {
  גרסה: "0.1.0",
  build_at: unix_ms,
  קבצים: [{path, sha256, size}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
פלט = INTEGRITY.sig.json = {מניפסט, חתום_על ידי: pub_hex, sig: sig_hex}

bots.h1_f:
